        Soz("Başkalarının alkışı geçtikten sonra da taşımak isteyeceğin bir karar ara.", "Look for a decision you would still want to live with after other people's applause fades.", "Ascend", "risk", sabitKimlik = "v5_risk_09"),
        Soz("Bilinmeyene yönelirken yanına bir soru al: Yanılırsam neyi korumak isterim?", "As you approach the unknown, ask yourself: If I am mistaken, what would I want to protect?", "Ascend", "risk", sabitKimlik = "v5_risk_10"),
