        Soz("Bir başvurunun yanıtını seçemem; yanıt beklerken kendime nasıl davranacağımı çalışabilirim.", "I cannot choose a reply to my application; I can practise how I treat myself while waiting.", "Ascend", "epiktetos", sabitKimlik = "v5_epiktetos_01"),
        Soz("Kısa bir mesajın eksik tonunu öfkeyle tamamladığımda, henüz söylenmemiş bir söze cevap veririm.", "If I fill a short message's missing tone with anger, I answer words that have not yet been spoken.", "Ascend", "epiktetos", sabitKimlik = "v5_epiktetos_02"),
        Soz("Bir övgü, bütün kişiliğim için verilmiş diploma değil; belirli bir anda alınmış geri bildirimdir.", "A compliment is feedback from a particular moment, not a certificate for my entire character.", "Ascend", "epiktetos", sabitKimlik = "v5_epiktetos_03"),
